import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [posts, setPosts] = useState([]);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [editId, setEditId] = useState(null);
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);

  const fetchPosts = async () => {
    const res = await axios.get('http://localhost:5000/posts');
    setPosts(res.data);
  };

  const handleSubmit = async () => {
    if (!title || !content) return alert('Please fill in all fields');

    const postData = new FormData();
    postData.append('title', title);
    postData.append('content', content);
    if (file) postData.append('image', file);

    if (editId) {
      await axios.put(`http://localhost:5000/posts/${editId}`, { title, content });
      alert('Post updated successfully');
      setEditId(null);
    } else {
      await axios.post('http://localhost:5000/posts', postData);
      alert('Post created successfully');
    }

    setTitle('');
    setContent('');
    setFile(null);
    setPreview(null);
    fetchPosts();
  };

  const handleEdit = (post) => {
    setEditId(post._id);
    setTitle(post.title);
    setContent(post.content);
    setPreview(post.image || null);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this post?')) {
      await axios.delete(`http://localhost:5000/posts/${id}`);
      alert('Post deleted');
      fetchPosts();
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFile(file);
    if (file) setPreview(URL.createObjectURL(file));
    else setPreview(null);
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  return (
    <>
      <header>📝 My Modern Blog</header>
      <main className="container">
        <div className="form-box">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Title"
          />
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Content"
          />
          <label className="file-card">
            <input type="file" onChange={handleFileChange} />
            <span>{file?.name || 'Choose an image'}</span>
          </label>
          {preview && <img src={preview} alt="preview" className="preview" />}
          <button onClick={handleSubmit}>
            {editId ? 'Update Post' : 'Create Post'}
          </button>
        </div>

        <div className="posts">
          {posts.map((post) => (
            <div key={post._id} className="post">
              <h3>{post.title}</h3>
              <p>{post.content}</p>
              {post.image && (
                <img
                  src={`http://localhost:5000/uploads/${post.image}`}
                  alt="post"
                  className="post-image"
                />
              )}
              <div className="actions">
                <button onClick={() => handleEdit(post)}>Edit</button>
                <button onClick={() => handleDelete(post._id)}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      </main>
      <footer>© 2025 Blog Platform. All rights reserved.</footer>
    </>
  );
}

export default App;
